def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, grid[y][x]))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] != background:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(cells)
    template = max(components, key=len)
    ys = [y for y, x, v in template]
    xs = [x for y, x, v in template]
    cy = (min(ys) + max(ys)) // 2
    cx = (min(xs) + max(xs)) // 2
    template_offsets = [(y-cy, x-cx, v) for y, x, v in template]
    out = [row[:] for row in grid]
    for component in components:
        if component is template:
            continue
        for r, c, _ in component:
            for dy, dx, color in template_offsets:
                yy, xx = r+dy, c+dx
                if 0 <= yy < h and 0 <= xx < w:
                    out[yy][xx] = color
    return out
